interface Observer<T> {
  subscribe(listener: (value: T) => void): () => void;
  getCurrentResult(): T;
}

export function mirrorObserverIntoStore<T>(
  observer: Observer<T>,
  writeStore: (value: T) => void,
): () => void {
  writeStore(observer.getCurrentResult());
  return observer.subscribe((value) => writeStore(value));
}

